#!/bin/bash
# Negative tests for check 21 (content extraction, ADR 0021): only workers call the content-extractor.
HERE=$(cd "$(dirname "$0")" && pwd); SRC=${REX_SRC:-$(cd "$HERE/../.." && pwd)}; PY=${PYTHON:-python3}
. "$HERE/neglib.sh"; pass=0; fail=0
run() { name="$1"; expect="$2"; mut="$3"
  T=$(mktemp -d); copy_repo "$SRC" "$T"; (cd $T && eval "$mut")
  out=$(REX=$T REX_SKIP_PHASE0_SCRIPT=${SKIP:-1} $PY "$HERE/check.py" 2>&1)
  if echo "$BASE" | grep -qF -- "$expect"; then echo "BASELINE $name (message already reported on the unmutated repo)"; base=$((base+1))
  elif echo "$out" | grep -qF -- "$expect"; then echo "CAUGHT  $name"; pass=$((pass+1)); else echo "MISSED  $name"; echo "$out" | head -8; fail=$((fail+1)); fi
  rm -rf $T; }
S=packages/contracts/openapi/services; A=docs/architecture.md
run "orchestrator may call extractor (kinds)" "architecture: orchestrator \"May call\" includes the content-extractor" "sed -i 's/| external SaaS only (Stripe); never tools |/| external SaaS only (Stripe), the content-extractor; never tools |/' $A"
run "gateway may call extractor (kinds)" "architecture: gateway \"May call\" includes the content-extractor" "sed -i 's/| orchestrator, \`x-rex-public\` tool operations (cache first) |/| orchestrator, the content-extractor, \`x-rex-public\` tool operations (cache first) |/' $A"
run "tool may call extractor (kinds)" "architecture: tool \"May call\" includes the content-extractor" "sed -i 's/never websites, another REx service or the content-extractor\./never websites; the content-extractor for pages./' $A"
run "workers lose extractor (kinds)" "workers \"May call\" must include the content-extractor" "sed -i 's/| tool services and the external services: the content-extractor and sitemap-extractor (cache first), the data-aggregator, the seo-auditor;/| tool services and the data-aggregator;/' $A"
run "communication row from orchestrator" "architecture communication: Orchestrator -> content-extractor" "sed -i 's/^| Worker -> content-extractor |/| Orchestrator -> content-extractor |/' $A"
run "communication row from gateway added" "architecture communication: Gateway -> content-extractor" "sed -i 's/^| Worker -> content-extractor | sync REST/| Gateway -> content-extractor | sync REST/' $A"
run "service map edge from orchestrator" "architecture service map: orchestrator -> content-extractor" "sed -i 's/^  workers -->|\"2: on miss, REST (content-extraction and page-audit calls)\"| extractor/  orchestrator -->|\"REST\"| extractor/' $A"
run "service map edge from tools added" "architecture service map: content_auditor -> content-extractor" "sed -i 's/^  workers -->|\"2: on miss, REST (content-extraction and page-audit calls)\"| extractor\[\"content-extractor (external, Go)\"\]/&\n  content_auditor -->|\"REST\"| extractor/' $A"
run "env var in gateway doc" "docs/services/gateway.md: CONTENT_EXTRACTOR_URL outside workers" "echo '- \`CONTENT_EXTRACTOR_URL\`: extractor base URL.' >> docs/services/gateway.md"
run "env var in tool spec" "CONTENT_EXTRACTOR_URL outside workers" "sed -i 's/LLM, no network\\./LLM, no network; uses CONTENT_EXTRACTOR_URL./' $S/citation-extractor.yaml"
run "env var rule removed from conventions" "conventions §12 must say CONTENT_EXTRACTOR_URL" "perl -0pi -e 's/\(base URLs of the external services\)\s+exist only in workers/(base URLs of the external services) are set in workers and the gateway/' docs/conventions.md"
run "orchestrator publishes extraction result" "content-extraction.completed: producers" "sed -i '/address: content-extraction.completed/{n;s/x-rex-producers: \[workers\]/x-rex-producers: [orchestrator]/}' packages/contracts/asyncapi/events.yaml"
run "extraction consumed by orchestrator" "content-extraction.requested must be consumed by workers only" "sed -i '/name: rex.workers.content-extraction/{n;s/consumer: workers/consumer: orchestrator/}' packages/contracts/bus/topology.yaml"
run "policy callers include gateway" "external.content-extractor.callers must be [workers]" "sed -i 's/callers: \[workers\]/callers: [workers, gateway]/' packages/contracts/cache/policy.yaml"
run "policy DEFAULT mark dropped" "extractContent ttl must be marked DEFAULT" "sed -i 's/        ttl: PT1H                                                # DEFAULT/        ttl: PT1H/' packages/contracts/cache/policy.yaml"
run "policy extractor TTL out of limits" "policy external.content-extractor.extractContent: ttl" "sed -i 's/        ttl: PT1H                                                # DEFAULT/        ttl: P999D # DEFAULT/' packages/contracts/cache/policy.yaml"
run "tool doc claims to call extractor" "content-auditor.md: claims to call the content-extractor" "echo '- Calls the content-extractor for the page text.' >> docs/services/content-auditor.md"
run "gateway doc claims to call extractor" "gateway.md: claims to call the content-extractor" "echo '- On a miss it calls the content-extractor and passes the text to the tool.' >> docs/services/gateway.md"
run "orchestrator doc claims to call extractor" "orchestrator.md: claims to call the content-extractor" "echo '- The optimization module calls the content-extractor directly.' >> docs/services/orchestrator.md"
run "orchestrator spec claims to call extractor" "orchestrator.yaml: claims to call the content-extractor" "sed -i 's/(a worker calls\$/(the orchestrator calls/' $S/orchestrator.yaml"
run "tool spec references extraction step" "references the extraction job or extractor interface" "sed -i 's/LLM, no network\\./LLM, no network; see extractContent./' $S/citation-extractor.yaml"
run "tool AGENTS template allows extractor" "tool-AGENTS.md.tmpl: claims to call the content-extractor" "sed -i 's/^- No network besides an LLM provider.s API: never call the content-extractor, never$/- Call the content-extractor for every page. Also/' docs/agents/tool-AGENTS.md.tmpl"
run "content-auditor fetches again" "content-auditor auditPage: must fetch nothing" "sed -i \"s/x-rex-limits: {llm: none, outboundFetch: none, notes: 'audits the page data/x-rex-limits: {llm: none, outboundFetch: one, fetchTimeout: PT5S, fetchMaxBytes: 2000000, notes: 'audits the page data/\" $S/content-auditor.yaml"
run "public schema tool fetches again" "schema-generator: a tool operation declares outbound fetches" "sed -i \"s/{p99: PT2S, llm: none, outboundFetch: none, notes: 'parses the data or HTML/{p99: PT2S, llm: none, outboundFetch: one, fetchTimeout: PT5S, fetchMaxBytes: 2000000, notes: 'parses the data or HTML/\" $S/schema-generator.yaml"
run "public URL rule removed" "URL-based public flows go through the orchestrator" "perl -0pi -e 's/URL-based public flow\s+goes through/URL-based public flow may skip/' docs/conventions.md"
run "ADR 0021 not Accepted" "ADR 0021 must be Accepted (decided by Jay)" "sed -i 's/^- \*\*Status:\*\* Accepted (decided by Jay)/- **Status:** Proposed/' docs/adr/0021-content-extraction.md"
run "ADR 0021 title loses workers" "ADR 0021 title must say workers" "sed -i '1s/.*/# 0021: Content extraction via external content-extractor/' docs/adr/0021-content-extraction.md"
run "amendment line missing" "ADR 0015 lacks its Amended line for ADR 0021" "sed -i '/0021-content-extraction.md))$/d' docs/adr/0015-stateless-workers.md"
run "ADR 0020 created" "ADR 0020 is reserved" "cp docs/adr/0000-template.md docs/adr/0020-route-loader.md"
run "superseded ADR marked Accepted" "ADR 0005 must stay Superseded" "sed -i 's/^- \*\*Status:\*\* Superseded by.*/- **Status:** Accepted (2026-11-22, accepted by Jay)/' docs/adr/0005-*.md"
run "index row still Proposed" "ADR index: 0016 must be listed as Accepted" "sed -i 's/^\(| \[0016\].*| \)Accepted (amended) |$/\1Proposed (amended) |/' docs/adr/README.md"
run "README status not accepted" "README status must say Phase 0 accepted by Jay on 2026-11-22" "sed -i 's/Phase 0 accepted by Jay on 2026-11-22/Phase 0 delivered/' README.md"
run "workers flow row removed" "workers doc flows table lacks content-extraction" "sed -i '/^| \`content-extraction\` |/d' docs/services/workers.md"
run "external kind row removed" "architecture kinds table rows" "sed -i '/^| external | content-extractor, sitemap-extractor, seo-auditor, data-aggregator |/d' $A"
run "extractor missing from service table" "architecture services table mismatch" "sed -i '/^| content-extractor | external | 5 |/d' $A"
# Jay's 2026-11-22 decisions: extractor contract, no tool fetches, llms.txt crawl
X=$S/content-extractor.yaml; P=packages/contracts/cache/policy.yaml; V=packages/contracts/vendoring.yaml
run "fetch switch returns" "lists a --fetch template switch" "sed -i 's/llms-txt-generator. There is no fetch switch: no tool fetches (ADR 0021)./llms-txt-generator; \`--fetch\` for content-auditor. Only some tools fetch./' docs/conventions.md"
run "undici re-approved" "still approves undici" "sed -i 's/^| \`cheerio\` | HTML parsing of the raw page passed in | content-auditor, schema-generator |/&\n| \`undici\` | HTTP client | tools |/' docs/conventions.md"
run "fetch helper in docs" "mentions a tool fetch helper" "echo '- \`src/fetch/\`: bounded fetch helper.' >> docs/architecture.md"
run "handoff copy missing" "handoff/content-extractor.openapi.yaml missing" "rm packages/contracts/handoff/content-extractor.openapi.yaml"
run "handoff section dropped" "vendoring.yaml handoff" "$PY -c \"import re;p='$V';s=open(p).read();open(p,'w').write(re.sub(r'\nhandoff:.*','\n',s,flags=re.S))\""
run "gateway vendors extractor" "gateway vendors content-extractor" "sed -i 's#^      - {target: contract/tools/content-auditor.yaml, from: openapi/services/content-auditor.yaml, how: bundle, fromPhase: 3}#&\n      - {target: contract/external/content-extractor.yaml, from: openapi/services/content-extractor.yaml, how: bundle, fromPhase: 3}#' $V"
run "workers stop vendoring extractor" "workers do not vendor content-extractor" "sed -i '/target: contract\/external\/content-extractor.yaml/d' $V"
run "specMajor back in policy" "specMajor comes from the spec" "sed -i 's/^    keyVersion: 1     # bump when the extractor/    specMajor: 1\n    keyVersion: 1     # bump when the extractor/' $P"
run "policy op name drift" "operations differ from its spec" "sed -i 's/^      extractContent:$/      extractPage:/' $P"
run "extractor gains auth" "content-extractor: spec must declare security: []" "sed -i 's/^security: \[\]   # reachable only from workers/security: [{bearer: []}]   # x/' $X"
run "extractor owner statement removed" "implemented in Go outside this repo" "sed -i 's/implemented in Go outside this repo/implemented elsewhere/' $X"
run "extractor limits not DEFAULT" "limits must be marked DEFAULT" "sed -i \"s/notes: 'DEFAULT values; per fetch/notes: 'per fetch/\" $X"
run "extractor limits lose fetch cap" "x-rex-limits must state maxDuration, fetchTimeout, fetchMaxBytes" "sed -i 's/fetchTimeout: PT10S, fetchMaxBytes: 2000000, notes/fetchTimeout: PT10S, notes/' $X"
run "extractor 422 code undocumented" "422 code target_blocked not documented" "sed -i 's/\`target_blocked\`/target-blocked/g' $X"
run "extractor include gains sitemap" "include must offer exactly robotsTxt, llmsTxt" "sed -i 's/enum: \[robotsTxt, llmsTxt\]/enum: [robotsTxt, llmsTxt, sitemap]/' $X"
run "extractor drops raw page" "Extraction.page must \$ref common FetchedPage" "sed -i 's#common.yaml\#/components/schemas/FetchedPage#common.yaml\#/components/schemas/FetchedFile#g' $X"
run "extractor gains links" "Extraction.links is back" "$PY -c \"import yaml,re;p='$X';s=open(p).read();d=yaml.safe_load(s);d['components']['schemas']['Extraction']['properties']['links']={'type':'array'};open(p,'w').write(yaml.safe_dump(d,sort_keys=False))\""
run "extractor takes only url" "ExtractionRequest must take url or html" "sed -i 's/required: \[html\]/required: [url, html]/' $X"
run "events lose extractor ref" "events.yaml must \$ref content-extractor ExtractionRequest" "sed -i \"s#content-extractor.yaml\#/components/schemas/ExtractionRequest'#\#/components/schemas/ContentExtractionRequest'#\" packages/contracts/asyncapi/events.yaml"
run "events copy extraction schema" "events.yaml copies the extraction schemas" "sed -i 's/^    LlmsTxtGenerationJob:$/    ContentExtraction:\n      type: object\n&/' packages/contracts/asyncapi/events.yaml"
SKIP=0 run "handoff copy edited (script)" "content-extractor.openapi.yaml" "echo '# edited' >> packages/contracts/handoff/content-extractor.openapi.yaml"
run "schema URL mode back" "URL mode is back" "$PY -c \"import yaml;p='$S/schema-generator.yaml';d=yaml.safe_load(open(p));d['components']['schemas']['FromUrl']={'type':'object','properties':{'url':{'type':'string'}}};open(p,'w').write(yaml.safe_dump(d,sort_keys=False))\""
run "llms request loses pages" "LlmsTxtRequest must take the page entries" "$PY -c \"import yaml;p='$S/llms-txt-generator.yaml';d=yaml.safe_load(open(p));s=d['components']['schemas']['LlmsTxtRequest'];b=[x for x in s['allOf'] if 'properties' in x][0];b['properties'].pop('pages');b['required']=['siteUrl'];open(p,'w').write(yaml.safe_dump(d,sort_keys=False))\""
run "conventions URL-mode exception back" "conventions §2 still lists URL-mode exceptions" "echo 'Exception: URL mode of validateLlmsTxt fetches one file.' >> docs/conventions.md"
run "conventions network rule removed" "conventions §2 must say tools never touch the network" "sed -i 's/Tools never touch the network/Tools rarely touch the network/' docs/conventions.md"
run "workers doc says workers fetch" "workers doc says workers fetch websites" "echo 'Workers fetch the page before calling the tool.' >> docs/services/workers.md"
run "workers audit flow skips the reference read" "content-audit must read page results by reference" "sed -i 's/^| \`content-audit\` | read the extraction \[by reference\]/| \`content-audit\` | read the extraction from the data-aggregator [first]/' docs/services/workers.md"
run "orchestrator doc loses discover key" "llms.txt crawl lacks llms:<llmsTxtId>:discover" "sed -i 's/llms:<llmsTxtId>:discover/llms:<llmsTxtId>:find/g' docs/services/orchestrator.md"
run "decided roadmap row reappears" "roadmap still lists the decided row" "sed -i 's/^| Membership tiers/| Who fetches a page | x | y |\n&/' docs/roadmap.md"
run "ADR 0021 amendment removed" "ADR 0021 lacks its dated amendment" "sed -i 's/^### 2026-11-22: REx defines the extractor contract/### Later: REx defines the extractor contract/' docs/adr/0021-content-extraction.md"
echo "caught $pass / $((pass+fail))"
[ "$fail" -eq 0 ]
